'use strict';
const $=id=>document.getElementById(id);
const palette={0:'#192824',10:'#2c6349',20:'#62825a',30:'#7a9465',40:'#657d4e',50:'#dbb384',60:'#82806a',70:'#e3e5dd',80:'#5799b6',90:'#4e8873',95:'#3d6d60',100:'#8d9876',200:'#a7e56d'};
const names={0:'No classified data',10:'Tree cover',20:'Shrubland',30:'Grassland',40:'Cropland',50:'Built-up',60:'Bare / sparse vegetation',70:'Snow and ice',80:'Permanent water',90:'Herbaceous wetland',95:'Mangroves',100:'Moss and lichen'};
const state={data:null,view:'compare',zoom:1,panX:0,panY:0,ranking:[],future:null,added:null};
const canvas=$('map'),ctx=canvas.getContext('2d');let baselineCanvas,futureCanvas,changeCanvas,geometry;
const params=new URLSearchParams(location.search);
for(const [id,min,max,step] of [['year',2021,2050,1],['demand',0,60,5]]){let n=Number(params.get(id));if(params.has(id)&&Number.isFinite(n))$(id).value=Math.round(Math.min(max,Math.max(min,n))/step)*step;}
if(params.has('trees'))$('trees').checked=params.get('trees')!=='0';
function rasterToCanvas(grid,added=null,changeOnly=false){const c=document.createElement('canvas');c.width=state.data.width;c.height=state.data.height;const ct=c.getContext('2d'),im=ct.createImageData(c.width,c.height);for(let i=0;i<grid.length;i++){let hex=changeOnly?(added&&added[i]?palette[200]:'#20352b'):(added&&added[i]?palette[200]:palette[grid[i]]||palette[0]);let j=i*4;im.data[j]=parseInt(hex.slice(1,3),16);im.data[j+1]=parseInt(hex.slice(3,5),16);im.data[j+2]=parseInt(hex.slice(5,7),16);im.data[j+3]=255;}ct.putImageData(im,0,0);return c;}
function makeRanking(){const d=state.data,protect=$('trees').checked;state.ranking=[];for(let i=0;i<d.grid.length;i++){let v=d.grid[i];if(v&&![50,70,80,90,95].includes(v)&&!(protect&&v===10))state.ranking.push(i);}state.ranking.sort((a,b)=>d.scores[a]-d.scores[b]||a-b);}
function summarize(grid){let counts={built:0,vegetation:0,water:0,other:0,total:0};for(const v of grid){if(!v)continue;counts.total++;if(v===50)counts.built++;else if(v===80)counts.water++;else if([10,20,30,40,90,95,100].includes(v))counts.vegetation++;else counts.other++;}return counts;}
function calculate(){if(!state.data)return;const d=state.data,year=+$('year').value,demand=+$('demand').value;state.future=Uint8Array.from(d.grid);state.added=new Uint8Array(d.grid.length);const requested=Math.floor(state.baseline.built*demand/100*(year-2021)/29);const allocated=Math.min(requested,state.ranking.length);let lostVegetation=0,lostTrees=0;for(let k=0;k<allocated;k++){const i=state.ranking[k];if([10,20,30,40,100].includes(d.grid[i]))lostVegetation++;if(d.grid[i]===10)lostTrees++;state.future[i]=50;state.added[i]=1;}state.requested=requested;state.allocated=allocated;state.lostTrees=lostTrees;state.summary=summarize(state.future);futureCanvas=rasterToCanvas(state.future,state.added);changeCanvas=rasterToCanvas(state.future,state.added,true);$('yearOut').textContent=year;$('demandOut').textContent='+'+demand+'%';$('futureBadge').textContent=year+' · What if?';$('splitYear').textContent=year+' scenario';$('newArea').textContent=(allocated*.01).toFixed(1);$('impactDescription').textContent=allocated<requested?((requested-allocated)*.01).toFixed(1)+' km² of requested growth cannot fit within eligible cells.':(lostVegetation*.01).toFixed(1)+' km² of mapped vegetation & crops converted. '+(lostTrees*.01).toFixed(1)+' km² of that is tree cover.';$('scope').textContent=(state.baseline.total*.01).toFixed(0)+' km² classified study grid · 100 m cells · Not an administrative boundary';document.querySelectorAll('[data-demand]').forEach(b=>b.classList.toggle('active',+b.dataset.demand===demand));renderBars();draw();}
function renderBars(){const b=state.baseline,f=state.summary,t=b.total;const categories=[['Built-up','built','#dbb384'],['Vegetation & crops','vegetation','#538665'],['Water','water','#5799b6'],['Other land','other','#82806a']];$('bars').innerHTML='<div class="key"><span>2021 baseline (faded) → selected scenario (solid)</span><span>Share of classified grid</span></div>'+categories.map(([label,key,color])=>{let bp=b[key]/t*100,fp=f[key]/t*100;return `<div class="barrow"><div class="barhead"><span>${label}</span><span>${bp.toFixed(1)}% → ${fp.toFixed(1)}%</span></div><div class="track"><i class="baselinebar" style="width:${bp}%;background:${color}"></i></div><div class="track"><i style="width:${fp}%;background:${color}"></i></div></div>`;}).join('');}
function getGeometry(w,h){const d=state.data,unit=Math.min(w/d.width,h/d.height)*state.zoom;return {unit,x:(w-d.width*unit)/2+state.panX,y:(h-d.height*unit)/2+state.panY};}
function labels(c,g){for(const p of state.data.landmarks){let x=g.x+p.x*g.unit,y=g.y+p.y*g.unit;c.font='10px sans-serif';let w=c.measureText(p.name).width;c.fillStyle='#0e211be8';c.fillRect(x-4,y-13,w+8,20);c.fillStyle='#ecf2dd';c.fillText(p.name,x,y);}}
function draw(){if(!state.data)return;const w=canvas.clientWidth,h=canvas.clientHeight,dpr=window.devicePixelRatio||1;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#13241d';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#23352b';ctx.lineWidth=.5;for(let x=0;x<w;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke();}for(let y=0;y<h;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}geometry=getGeometry(w,h);const g=geometry,d=state.data;ctx.imageSmoothingEnabled=false;if(state.view==='compare'){ctx.drawImage(baselineCanvas,g.x,g.y,d.width*g.unit,d.height*g.unit);ctx.save();let split=w*+$('split').value/100;ctx.beginPath();ctx.rect(split,0,w-split,h);ctx.clip();ctx.drawImage(futureCanvas,g.x,g.y,d.width*g.unit,d.height*g.unit);ctx.restore();}else ctx.drawImage(changeCanvas,g.x,g.y,d.width*g.unit,d.height*g.unit);labels(ctx,g);$('splitline').style.left=$('split').value+'%';$('splitline').hidden=state.view!=='compare';let km=50*g.unit>180?1:5;$('scale').innerHTML='<span>'+km+' km</span><span style="display:inline-block;vertical-align:middle;border-top:2px solid #b3c3b6;margin-left:6px;width:'+(km*10*g.unit)+'px"></span>';}
function resetMap(){state.zoom=1;state.panX=state.panY=0;$('tooltip').hidden=true;draw();}
function updateURL(){const u=new URL(location.href);u.searchParams.set('year',$('year').value);u.searchParams.set('demand',$('demand').value);u.searchParams.set('trees',$('trees').checked?'1':'0');history.replaceState(null,'',u);return u.href;}
for(const id of ['year','demand'])$(id).addEventListener('input',()=>{calculate();updateURL();});$('trees').addEventListener('change',()=>{makeRanking();calculate();updateURL();});$('split').addEventListener('input',draw);$('resetView').onclick=resetMap;for(const b of document.querySelectorAll('[data-demand]'))b.onclick=()=>{$('demand').value=b.dataset.demand;calculate();updateURL();};for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{state.view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(t=>t.classList.toggle('active',t===b));document.querySelector('.comparecontrol').style.visibility=state.view==='compare'?'visible':'hidden';draw();};
function zoom(factor){state.zoom=Math.min(5,Math.max(1,state.zoom*factor));if(state.zoom===1)state.panX=state.panY=0;draw();}$('zoomIn').onclick=()=>zoom(1.3);$('zoomOut').onclick=()=>zoom(1/1.3);canvas.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.12:1/1.12);},{passive:false});let drag=null;canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false};});canvas.addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.lastX,dy=e.clientY-drag.lastY;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>4)drag.moved=true;if(drag.moved){state.panX+=dx;state.panY+=dy;$('tooltip').hidden=true;draw();}drag.lastX=e.clientX;drag.lastY=e.clientY;});canvas.addEventListener('pointerup',e=>{if(drag&&!drag.moved)inspect(e);drag=null;});canvas.addEventListener('pointercancel',()=>drag=null);
function inspect(e){if(!geometry)return;const rect=canvas.getBoundingClientRect(),g=geometry,d=state.data;let x=Math.floor((e.clientX-rect.left-g.x)/g.unit),y=Math.floor((e.clientY-rect.top-g.y)/g.unit);if(x<0||y<0||x>=d.width||y>=d.height){$('tooltip').hidden=true;return;}let i=y*d.width+x,original=names[d.grid[i]]||'Other';$('tooltip').innerHTML='<strong>100 m study cell</strong><br>2021: '+original+'<br>'+$('year').value+': '+(state.added[i]?'Built-up (simulated)':original+' (unchanged)');$('tooltip').hidden=false;}
$('share').onclick=async()=>{const u=updateURL();try{await navigator.clipboard.writeText(u);$('status').textContent='Scenario link copied. Anyone opening it sees your assumptions.';}catch{$('status').textContent='Copy this URL: '+u;}};
$('export').onclick=()=>{if(!state.data)return;let c=document.createElement('canvas');c.width=1200;c.height=1000;let ct=c.getContext('2d');ct.fillStyle='#101c1a';ct.fillRect(0,0,1200,1000);ct.fillStyle='#c7f186';ct.font='bold 27px sans-serif';ct.fillText('earth2050 / HYDERABAD',45,55);ct.fillStyle='#f1f1e7';ct.font='32px sans-serif';ct.fillText('What if the built-up footprint grew by '+$('demand').value+'%?',45,105);ct.fillStyle='#a3b4a8';ct.font='18px sans-serif';ct.fillText('Scenario year '+$('year').value+' · '+($('trees').checked?'Mapped tree cover protected':'Mapped tree cover eligible for conversion'),45,140);let d=state.data,unit=Math.min(1110/d.width,660/d.height),x=(1200-d.width*unit)/2,y=170;ct.imageSmoothingEnabled=false;ct.drawImage(futureCanvas,x,y,d.width*unit,d.height*unit);ct.fillStyle='#c7f186';ct.font='21px sans-serif';ct.fillText('+'+(state.allocated*.01).toFixed(1)+' km² simulated built-up · Green = additional development',45,865);ct.fillStyle='#c0cbbb';ct.font='16px sans-serif';ct.fillText('Observed baseline: ESA WorldCover 2021 · Generalized to 100 m · Rule-based scenario',45,899);ct.fillText('Not a validated prediction · Study window, not official city boundary · Neelima Donkada',45,925);ct.font='12px sans-serif';ct.fillText(d.attribution,45,960);let a=document.createElement('a');a.download='Earth2050-Hyderabad-'+$('year').value+'.png';a.href=c.toDataURL('image/png');a.click();$('status').textContent='Scenario image prepared for download.';};
function jump(){document.querySelector('.lab').scrollIntoView({behavior:'smooth',block:'start'});}$('tryTrees').onclick=()=>{$('trees').checked=!$('trees').checked;$('year').value=2050;makeRanking();calculate();updateURL();jump();};$('tryGrowth').onclick=()=>{$('year').value=2050;$('demand').value=+$('demand').value===45?10:45;calculate();updateURL();jump();};$('tryBaseline').onclick=()=>{$('year').value=2021;calculate();updateURL();resetMap();jump();};window.addEventListener('resize',draw);
async function start(){try{const r=await fetch('data/hyderabad.json');if(!r.ok)throw Error('Data request failed ('+r.status+')');const d=await r.json();if(d.grid.length!==d.width*d.height||d.scores.length!==d.grid.length)throw Error('Dataset dimensions do not match');state.data=d;state.baseline=summarize(d.grid);baselineCanvas=rasterToCanvas(d.grid);makeRanking();calculate();$('loading').hidden=true;$('loading').style.display='none';$('provenance').textContent='Source tile: '+d.sourceUrl+' | CRS: '+d.crs+' | Working grid: '+d.width+' × '+d.height+' | Baseline: '+d.baselineYear+'.';}catch(e){$('loading').textContent='The real land-cover dataset could not load. Please refresh. '+e.message;console.error(e);}}
start();
